parameters.parameter:
var parts = value.trim().split(/\s+/);
var token = parts[0];
if (typeof token === 'undefined') return 0;
token = token.replace(/^0x/i, '');
if (!/^[0-9a-fA-F]{1,2}$/.test(token)) {
    throw 'Unexpected MGP fault mask format: ' + value;
}
var octetValue = parseInt(token, 16);
return (octetValue & 128) ? 1 : 0;

